import 'package:flutter/material.dart';import 'package:intl/intl.dart';import '../../services/attendance_service.dart';import '../../services/auth_service.dart';class AttendanceScreen extends StatefulWidget {  const AttendanceScreen({super.key});  @override  State<AttendanceScreen> createState() => _AttendanceScreenState();}class _AttendanceScreenState extends State<AttendanceScreen> {  final _attendanceService = AttendanceService();  final _authService = AuthService();  bool _isLoading = false;  bool _checkingLocation = false;  String? _locationStatus;  double? _currentLatitude;  double? _currentLongitude;  double? _distanceFromOffice;  @override  void initState() {    super.initState();    _checkLocation();  }  Future<void> _checkLocation() async {    setState(() => _checkingLocation = true);    try {      final position = await _attendanceService.getCurrentLocation();      final distance = _attendanceService.calculateDistance(        position.latitude,        position.longitude,      );      setState(() {        _currentLatitude = position.latitude;        _currentLongitude = position.longitude;        _distanceFromOffice = distance;                if (distance <= AttendanceService.maxDistanceInMeters) {          _locationStatus = 'Within office range (${distance.toStringAsFixed(1)}m)';        } else {          _locationStatus = 'Too far from office (${distance.toStringAsFixed(1)}m away)';        }      });    } catch (e) {      setState(() {        _locationStatus = 'Error: ${e.toString()}';      });    } finally {      setState(() => _checkingLocation = false);    }  }  Future<void> _markAttendance() async {    if (_currentLatitude == null || _currentLongitude == null) {      ScaffoldMessenger.of(context).showSnackBar(        const SnackBar(          content: Text('Please wait for location to load'),          backgroundColor: Colors.orange,        ),      );      return;    }    setState(() => _isLoading = true);    try {      final currentUser = await _authService.getCurrentAppUser();      if (currentUser == null) {        throw Exception('User not found');      }      await _attendanceService.markAttendance(        staffId: currentUser.id,        staffName: currentUser.name,        latitude: _currentLatitude!,        longitude: _currentLongitude!,      );      if (mounted) {        ScaffoldMessenger.of(context).showSnackBar(          const SnackBar(            content: Text('Attendance marked successfully!'),            backgroundColor: Colors.green,          ),        );        Navigator.of(context).pop();      }    } catch (e) {      if (mounted) {        ScaffoldMessenger.of(context).showSnackBar(          SnackBar(            content: Text(e.toString()),            backgroundColor: Colors.red,          ),        );      }    } finally {      if (mounted) {        setState(() => _isLoading = false);      }    }  }  @override  Widget build(BuildContext context) {    final isWithinRange = _distanceFromOffice != null &&        _distanceFromOffice! <= AttendanceService.maxDistanceInMeters;    return Scaffold(      appBar: AppBar(        title: const Text('Mark Attendance'),      ),      body: Padding(        padding: const EdgeInsets.all(24),        child: Column(          mainAxisAlignment: MainAxisAlignment.center,          crossAxisAlignment: CrossAxisAlignment.stretch,          children: [            Icon(              _checkingLocation                  ? Icons.location_searching                  : isWithinRange                      ? Icons.check_circle                      : Icons.location_off,              size: 120,              color: _checkingLocation                  ? Colors.blue                  : isWithinRange                      ? Colors.green                      : Colors.red,            ),            const SizedBox(height: 32),            Text(              _checkingLocation                  ? 'Checking your location...'                  : _locationStatus ?? 'Location unavailable',              style: Theme.of(context).textTheme.headlineSmall,              textAlign: TextAlign.center,            ),            const SizedBox(height: 24),            if (_currentLatitude != null && _currentLongitude != null) ...[              Card(                child: Padding(                  padding: const EdgeInsets.all(16),                  child: Column(                    children: [                      Text(                        'Your Current Location',                        style: Theme.of(context).textTheme.titleMedium,                      ),                      const SizedBox(height: 8),                      Text(                        'Lat: ${_currentLatitude!.toStringAsFixed(6)}',                        style: Theme.of(context).textTheme.bodyMedium,                      ),                      Text(                        'Lng: ${_currentLongitude!.toStringAsFixed(6)}',                        style: Theme.of(context).textTheme.bodyMedium,                      ),                      const SizedBox(height: 8),                      Text(                        'Distance from office: ${_distanceFromOffice?.toStringAsFixed(1) ?? '---'}m',                        style: Theme.of(context).textTheme.bodyLarge?.copyWith(                              fontWeight: FontWeight.bold,                              color: isWithinRange ? Colors.green : Colors.red,                            ),                      ),                    ],                  ),                ),              ),              const SizedBox(height: 24),            ],            if (!_checkingLocation && _currentLatitude != null)              ElevatedButton.icon(                onPressed: _isLoading ? null : _markAttendance,                icon: _isLoading                    ? const SizedBox(                        height: 20,                        width: 20,                        child: CircularProgressIndicator(                          strokeWidth: 2,                          color: Colors.white,                        ),                      )                    : const Icon(Icons.fingerprint),                label: Text(                  _isLoading ? 'Marking...' : 'Mark Attendance',                  style: const TextStyle(fontSize: 18),                ),                style: ElevatedButton.styleFrom(                  padding: const EdgeInsets.symmetric(vertical: 16),                  backgroundColor: isWithinRange                      ? Theme.of(context).colorScheme.primary                      : Colors.grey,                ),              ),            const SizedBox(height: 16),            if (!_checkingLocation)              OutlinedButton.icon(                onPressed: _checkLocation,                icon: const Icon(Icons.refresh),                label: const Text('Refresh Location'),              ),            if (!isWithinRange && _currentLatitude != null)              Padding(                padding: const EdgeInsets.only(top: 16),                child: Text(                  'Note: You must be within ${AttendanceService.maxDistanceInMeters}m of the office to mark attendance.',                  style: Theme.of(context).textTheme.bodySmall,                  textAlign: TextAlign.center,                ),              ),          ],        ),      ),    );  }}